import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"Introduction","description":"KiriVers is a self-hosted software update service: you publish artifacts; apps check and download updates.","frontmatter":{"title":"Introduction","description":"KiriVers is a self-hosted software update service: you publish artifacts; apps check and download updates."},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md","lastUpdated":1790057721000}`),a={name:`en/guide/index.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>KiriVers is a <strong>self-hosted software update service</strong>. You publish installers or firmware; applications query this service and download updates. It is not git, and it does not replace App Store, Google Play, or Microsoft Store review.</p><h2 id="runtime-shape" tabindex="-1">Runtime shape <a class="header-anchor" href="#runtime-shape" aria-label="Permalink to “Runtime shape”">​</a></h2><p>One process exposes two planes:</p><table tabindex="0"><thead><tr><th>Plane</th><th>Default address</th><th>Role</th></tr></thead><tbody><tr><td>Client plane</td><td><code>:8080</code></td><td>Update check, downloads, store feeds, telemetry, announcements</td></tr><tr><td>Admin plane</td><td><code>:8081</code></td><td>Admin console SPA and CI agent</td></tr></tbody></table><p>Official Release binaries embed the admin UI. Operators do not deploy frontend static files separately. PostgreSQL is required; Redis is optional (see <a href="/en/guide/install/">Install</a> and <a href="/en/guide/config/cache">Cache</a>).</p><p>The CLI is <code>kirivers</code> / <code>kirivers server</code>, plus local <code>kirivers admin add|delete|list|reset-password|clear-2fa</code>. There is no release subcommand and no <code>kirivers listen</code>.</p><h2 id="two-integration-paths" tabindex="-1">Two integration paths <a class="header-anchor" href="#two-integration-paths" aria-label="Permalink to “Two integration paths”">​</a></h2><ol><li><strong>Native JSON</strong>: the application calls the client plane (<code>POST .../update/check</code>). This fits first-party desktop, server, and firmware clients. Official <a href="/en/api/sdk/">SDKs</a> wrap this path only.</li><li><strong>Store listings</strong>: create a listing in the console and point Electron / Sparkle / Tauri (and similar) at the listing URL. Native SDKs <strong>do not</strong> consume feeds.</li></ol><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h2><ul><li>App Store / Play / Microsoft Store publishing.</li><li>Acting as a Linux distro repository (APT / RPM / Flatpak).</li><li>Hosting this documentation site on the admin plane <code>GET /</code>.</li></ul><h2 id="reading-order" tabindex="-1">Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to “Reading order”">​</a></h2><ol><li><a href="/en/guide/install/">Choose an install path</a> → YAML → <a href="/en/guide/config/bootstrap-admin">create the first admin</a></li><li>After login, follow <a href="/en/admin/quick-start">Admin → Quick start</a> to publish the first version</li><li>Use <a href="/en/guide/features/">Feature guides</a> for channels, gray rollout, incremental updates, announcements</li><li>Then pick a <a href="/en/guide/scenarios/">scenario</a> for the application type</li></ol>`,13)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};